package campus.models;

import java.sql.Timestamp;

/**
 * Model representing an Audit Trail entry generated by MySQL DBMS triggers.
 */
public class AuditRecord {
    private int auditId;
    private String tableName;
    private String actionType;
    private String recordId;
    private String details;
    private Timestamp changedAt;

    public AuditRecord(int auditId, String tableName, String actionType, String recordId, String details, Timestamp changedAt) {
        this.auditId = auditId;
        this.tableName = tableName;
        this.actionType = actionType;
        this.recordId = recordId;
        this.details = details;
        this.changedAt = changedAt;
    }

    public void displayDetails() {
        System.out.printf("[%d] [%s] %-18s on Table: %-15s (Record ID: %s)%n",
                auditId, changedAt.toString().substring(0, 19), actionType, tableName, recordId);
        System.out.printf("    Details: %s%n", details);
    }

    public int getAuditId() {
        return auditId;
    }

    public String getTableName() {
        return tableName;
    }

    public String getActionType() {
        return actionType;
    }

    public String getRecordId() {
        return recordId;
    }

    public String getDetails() {
        return details;
    }

    public Timestamp getChangedAt() {
        return changedAt;
    }
}
